191				if err != nil || !res.Confirmed || res.Block == nil {
192					t.Fatalf("empty block should confirm on vote %d: %+v %v", tc.pendingVotes+1, res, err)
193				}
194				if len(res.Block.TxIDs) != 0 || res.Block.ID != local.BlockID {
195					t.Fatalf("confirmed empty block wrong: %+v", res.Block)
196				}
197				if n.CurrentRound() != 2 || n.Height() != 1 {
