204			})
205		}
206	}
207	
208	// 票数归属与完整名单计数：六人名单中一个候选四票、另一个候选一票，
209	// 五个人已投票仍不能确认任何候选——未投票者始终计入名单人数，比例不能拿
210	// 实际参与人数计算。最后一人投给已有四票的候选后，它才得到足够的五票。
211	// 胜出者不是本地提议时，确认块的标识与交易顺序仍来自胜出候选。
212	func TestQuorumVoteOwnershipAndNonLocalWinner(t *testing.T) {
213		keys := genKeys(t, 6)
214		n, _ := newTestNode(t, keys, 10)
215		a1 := NewTransaction(keys[0].priv, 1, []byte("a1"), 1, 100)
216		b1 := NewTransaction(keys[1].priv, 1, []byte("b1"), 5, 100)
217		n.Submit(a1)
218		n.Submit(b1)
219		local, _ := n.Propose() // 打包按费用：b1 先、a1 后。
220		if fmt.Sprint(local.TxIDs) != fmt.Sprint([]string{b1.ID(), a1.ID()}) {
221			t.Fatalf("setup: local proposal = %v, want [b1 a1]", local.TxIDs)
222		}
223		// 竞争候选使用相反的交易顺序，将作为非本地候选胜出。
224		altList := []string{a1.ID(), b1.ID()}
225		altID := registerMust(t, n, 1, altList)
226		if altID == local.BlockID {
227			t.Fatal("test setup: alt candidate must differ from local")
228		}
229	
230		// 四人投竞争候选：4 票恰好等于六人的三分之二，仍不足。
231		for i := 0; i < 4; i++ {
232			res, err := n.Vote(keys[i].pub, 1, altID)
233			if err != nil || !res.Counted || res.Confirmed {
234				t.Fatalf("alt vote %d must count without confirming: %+v %v", i+1, res, err)
235			}
236		}
237		// 第五人投本地候选：两个候选分别为 4 票与 1 票，均不能确认。
238		res, err := n.Vote(keys[4].pub, 1, local.BlockID)
239		if err != nil || !res.Counted || res.Confirmed {
240			t.Fatalf("local vote must count without confirming: %+v %v", res, err)
241		}
242		if n.CurrentRound() != 1 || n.Height() != 0 {
243			t.Fatalf("round=%d height=%d, split 4/1 votes must not decide", n.CurrentRound(), n.Height())
244		}
245		altView := findCandidate(t, n, 1, altID)
246		localView := findCandidate(t, n, 1, local.BlockID)
247		if altView.Result != CandidatePending || len(altView.Voters) != 4 {
248			t.Fatalf("alt candidate wrong before quorum: %+v", altView)
249		}
250		if localView.Result != CandidatePending || len(localView.Voters) != 1 {
251			t.Fatalf("local candidate wrong before quorum: %+v", localView)
252		}
253		rc, _ := n.Candidates(1)
254		if len(rc.Unvoted) != 1 || fmt.Sprintf("%x", rc.Unvoted[0]) != fmt.Sprintf("%x", keys[5].pub) {
255			t.Fatalf("only keys[5] should be unvoted: %x", rc.Unvoted)
256		}
257		// 两笔交易仍处于等待投票状态。
258		for _, id := range []string{a1.ID(), b1.ID()} {
259			if info, _ := n.Tx(id); info.Status != StatusProposed {
260				t.Fatalf("tx %s status = %s, want proposed", id, info.Status)
261			}
262		}
263	
264		// 重复投原候选不增票，不能借重复请求跨过门槛；改投仍被一人一轮一票规则拒绝。
265		dup, err := n.Vote(keys[0].pub, 1, altID)
266		if err != nil || dup.Counted || dup.Confirmed {
267			t.Fatalf("duplicate vote must not count or confirm: %+v %v", dup, err)
268		}
269		if _, err := n.Vote(keys[0].pub, 1, local.BlockID); reason(err) != ReasonAlreadyVoted {
270			t.Fatalf("switching candidate got %v, want %s", err, ReasonAlreadyVoted)
271		}
272		assertRoundStillOpen(t, n, altID, 6, 4, 5, a1.ID())
273	
274		// 最后一名未投票者投给已有四票的候选：第五票严格超过三分之二，立即确认。
275		res, err = n.Vote(keys[5].pub, 1, altID)
276		if err != nil || !res.Counted || !res.Confirmed || res.Block == nil {
277			t.Fatalf("fifth distinct alt vote should confirm: %+v %v", res, err)
278		}
279		if n.CurrentRound() != 2 || n.Height() != 1 {
280			t.Fatalf("round=%d height=%d, want 2/1", n.CurrentRound(), n.Height())
281		}
282		// 确认块标识与交易顺序来自非本地的胜出候选。
283		if res.Block.ID != altID || fmt.Sprint(res.Block.TxIDs) != fmt.Sprint(altList) {
284			t.Fatalf("confirming block must come from non-local winner: %+v", res.Block)
285		}
286		blk, _ := n.BlockAt(1)
287		if blk.ID != altID || fmt.Sprint(blk.TxIDs) != fmt.Sprint(altList) || blk.PreviousID != "" {
288			t.Fatalf("stored block must match non-local winner: %+v", blk)
289		}
290	
291		// 查询旧轮：胜出者与落选者的结果和实际得票一一对应，投票者不重复。
292		rc, _ = n.Candidates(1)
293		if !rc.Ended || rc.UnconfirmedEnd || len(rc.Unvoted) != 0 {
294			t.Fatalf("decided round record wrong: %+v", rc)
295		}
296		altView = findCandidate(t, n, 1, altID)
297		localView = findCandidate(t, n, 1, local.BlockID)
298		if altView.Result != CandidateWon || len(altView.Voters) != 5 {
299			t.Fatalf("winner view wrong: %+v", altView)
300		}
301		wantAltVoters := map[string]bool{}
302		for _, i := range []int{0, 1, 2, 3, 5} {
303			wantAltVoters[fmt.Sprintf("%x", keys[i].pub)] = true
304		}
305		gotAltVoters := map[string]bool{}
306		for _, v := range altView.Voters {
307			k := fmt.Sprintf("%x", v)
308			if gotAltVoters[k] {
309				t.Fatalf("voter %s appears more than once", k)
310			}
311			gotAltVoters[k] = true
312		}
313		if fmt.Sprint(gotAltVoters) != fmt.Sprint(wantAltVoters) {
314			t.Fatalf("winner voters = %v, want %v", gotAltVoters, wantAltVoters)
315		}
316		if localView.Result != CandidateLost || len(localView.Voters) != 1 ||
317			fmt.Sprintf("%x", localView.Voters[0]) != fmt.Sprintf("%x", keys[4].pub) {
318			t.Fatalf("loser view must keep its single real vote: %+v", localView)
319		}
320	
321		// 胜出候选中的交易按其顺序确认一次。
322		for _, id := range altList {
323			info, _ := n.Tx(id)
324			if info.Status != StatusConfirmed || info.BlockID != altID || info.BlockHeight != 1 {
325				t.Fatalf("winner tx %s wrong: %+v", id, info)
326			}
327		}
328	}
